
const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#10251d\">\n  <meta name=\"description\" content=\"A face-to-face English coach with Tavus perception, Fluent Me learning memory, and your own fluent voice.\">\n  <meta property=\"og:title\" content=\"Fluent Me × Tavus\">\n  <meta property=\"og:description\" content=\"Meet the fluent version of you.\">\n  <meta property=\"og:image\" content=\"/static/og.png\">\n  <title>Fluent Me × Tavus — live practice</title>\n  <link rel=\"stylesheet\" href=\"/static/live.css\">\n  <script crossorigin src=\"https://unpkg.com/@daily-co/daily-js\"></script>\n</head>\n<body data-room-state=\"booting\">\n  <header class=\"topbar\">\n    <a class=\"brand\" href=\"/\" aria-label=\"Fluent Me home\">\n      <span class=\"brand-mark\" aria-hidden=\"true\"><i></i><i></i><i></i></span>\n      <span>Fluent Me</span>\n    </a>\n    <nav class=\"primary-nav\" aria-label=\"Primary navigation\">\n      <a class=\"active\" href=\"/\">Live practice</a>\n      <a href=\"#mirror-card\">Mirror lab</a>\n      <a href=\"#report-card\">Learning memory</a>\n    </nav>\n    <button class=\"connection-pill\" id=\"connection-pill\" type=\"button\" aria-haspopup=\"dialog\">\n      <span class=\"status-dot\"></span><span id=\"connection-label\">Checking Tavus…</span>\n    </button>\n  </header>\n\n  <main class=\"page-shell\">\n    <section class=\"intro\" aria-labelledby=\"page-title\">\n      <div>\n        <p class=\"eyebrow\">Fluent Me <span>×</span> Tavus</p>\n        <h1 id=\"page-title\">Meet the fluent version of you.</h1>\n        <p class=\"lede\">Kai sees the conversation, hears how you deliver it, and remembers what you need to practice next. Your corrections come back in your own cloned voice.</p>\n      </div>\n      <div class=\"focus-picker\" role=\"group\" aria-label=\"Practice focus\">\n        <span>Today I want to</span>\n        <button class=\"focus-chip selected\" type=\"button\" data-focus=\"conversation\">have a conversation</button>\n        <button class=\"focus-chip\" type=\"button\" data-focus=\"interview\">practice an interview</button>\n        <button class=\"focus-chip\" type=\"button\" data-focus=\"story\">tell a story</button>\n      </div>\n    </section>\n\n    <section class=\"room-grid\" aria-label=\"Practice room\">\n      <article class=\"stage-card\">\n        <header class=\"stage-head\">\n          <div>\n            <span class=\"stage-kicker\">Kai · AI English coach</span>\n            <span class=\"stage-state\" id=\"stage-state\">Preparing the room</span>\n          </div>\n          <div class=\"live-clock\" id=\"live-clock\" hidden><i></i><span>Live</span><time id=\"timer\">00:00</time></div>\n        </header>\n\n        <div class=\"video-stage\" id=\"video-stage\">\n          <div class=\"stage-glow\" aria-hidden=\"true\"></div>\n          <div class=\"preview-label\" id=\"preview-label\">Preview mode · sample signals</div>\n          <div class=\"stage-placeholder\" id=\"stage-placeholder\">\n            <div class=\"signal-portrait\" aria-hidden=\"true\">\n              <div class=\"orbit orbit-one\"></div>\n              <div class=\"orbit orbit-two\"></div>\n              <div class=\"portrait-core\"><span>K</span><b></b></div>\n            </div>\n            <div class=\"stage-copy\">\n              <p class=\"stage-copy-kicker\" id=\"stage-copy-kicker\">Face-to-face practice</p>\n              <h2 id=\"stage-title\">A coach that notices the whole conversation.</h2>\n              <p id=\"stage-description\">Microphone access is required for live practice. Camera is optional and enables visual context.</p>\n            </div>\n            <label class=\"camera-choice\" id=\"camera-choice\">\n              <input id=\"camera-enabled\" type=\"checkbox\" checked>\n              <span><b>Camera perception</b><small>Let Raven use visible context. No emotion scoring.</small></span>\n            </label>\n            <div class=\"stage-actions\">\n              <button class=\"button primary\" id=\"start-button\" type=\"button\" disabled>Loading…</button>\n              <button class=\"button quiet\" id=\"guide-button\" type=\"button\">How it connects</button>\n            </div>\n          </div>\n          <div class=\"speaking-cue\" id=\"speaking-cue\" hidden><span></span><b id=\"speaking-label\">Kai is speaking</b></div>\n        </div>\n\n        <footer class=\"stage-controls\">\n          <p id=\"room-note\">Camera and microphone stay off until you start.</p>\n          <div>\n            <button class=\"control-button\" id=\"sample-button\" type=\"button\" hidden>Run sample turn</button>\n            <button class=\"control-button danger\" id=\"end-button\" type=\"button\" hidden>End session</button>\n          </div>\n        </footer>\n\n        <div class=\"perception-ribbon\" aria-live=\"polite\">\n          <div class=\"ribbon-intro\">\n            <span class=\"signal-icon\" aria-hidden=\"true\">R</span>\n            <div><b>Raven context</b><small>Observations help Kai respond; they never change your language score.</small></div>\n          </div>\n          <div class=\"signal-card\">\n            <span>Vocal delivery</span>\n            <p id=\"audio-perception\">Waiting for a complete user turn.</p>\n          </div>\n          <div class=\"signal-card\">\n            <span>Visible context</span>\n            <p id=\"visual-perception\">Camera context will appear here when available.</p>\n          </div>\n        </div>\n      </article>\n\n      <aside class=\"coach-rail\" aria-label=\"Learning feedback\">\n        <section class=\"rail-card focus-card\">\n          <header><span class=\"rail-index\">01</span><div><p class=\"rail-kicker\">Today’s focus</p><h2>Memory in the conversation</h2></div></header>\n          <p class=\"rail-explain\">Kai quietly creates natural openings for patterns that are due for review.</p>\n          <div class=\"memory-targets\" id=\"memory-targets\">\n            <span class=\"target-skeleton\"></span><span class=\"target-skeleton short\"></span>\n          </div>\n        </section>\n\n        <section class=\"rail-card score-card\">\n          <header><span class=\"rail-index\">02</span><div><p class=\"rail-kicker\">This turn</p><h2>Language signal</h2></div></header>\n          <div class=\"score-summary\">\n            <strong id=\"turn-score\">—</strong>\n            <span><b id=\"score-caption\">Waiting for your first turn</b><small id=\"score-note\">Grammar and vocabulary are graded separately from perception.</small></span>\n          </div>\n          <div class=\"score-grid\">\n            <div><span>Grammar</span><b id=\"score-grammar\">—</b><i><em id=\"bar-grammar\"></em></i></div>\n            <div><span>Vocabulary</span><b id=\"score-vocab\">—</b><i><em id=\"bar-vocab\"></em></i></div>\n            <div class=\"unavailable\"><span>Fluency</span><b id=\"score-fluency\">n/a</b><small>needs timing</small></div>\n            <div class=\"unavailable\"><span>Pronunciation</span><b id=\"score-pron\">n/a</b><small>ASR-based only</small></div>\n          </div>\n        </section>\n\n        <section class=\"rail-card mirror-card\" id=\"mirror-card\">\n          <header><span class=\"rail-index\">03</span><div><p class=\"rail-kicker\">Mirror moment</p><h2>Hear the fluent you</h2></div></header>\n          <div class=\"mirror-empty\" id=\"mirror-empty\">\n            <span class=\"mirror-wave\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span>\n            <p>Your most useful recast will appear here—spoken in your cloned voice when connected.</p>\n          </div>\n          <div class=\"mirror-result\" id=\"mirror-result\" hidden>\n            <span class=\"before-label\">You said</span>\n            <p class=\"before-text\" id=\"mirror-before\"></p>\n            <span class=\"after-label\">A more natural version</span>\n            <blockquote id=\"mirror-after\"></blockquote>\n            <button class=\"mirror-play\" id=\"mirror-play\" type=\"button\"><span>▶</span><b>Hear the fluent me</b><small id=\"mirror-engine\">Your cloned voice</small></button>\n          </div>\n        </section>\n      </aside>\n    </section>\n\n    <section class=\"transcript-card\" aria-labelledby=\"transcript-title\">\n      <header>\n        <div><p class=\"rail-kicker\">Conversation trail</p><h2 id=\"transcript-title\">What happened in the room</h2></div>\n        <span id=\"transcript-count\">No turns yet</span>\n      </header>\n      <div class=\"transcript\" id=\"transcript\">\n        <div class=\"transcript-empty\" id=\"transcript-empty\">\n          <span>“</span><p>Your conversation and learning moments will collect here—not as a wall of chat, but as evidence you can revisit.</p>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"report-card\" id=\"report-card\" hidden aria-live=\"polite\">\n      <div class=\"report-heading\"><p class=\"eyebrow\">Session complete</p><h2 id=\"report-title\">Nice work. Your learning memory is updated.</h2><p id=\"report-summary\">Finalizing your recap…</p></div>\n      <div class=\"report-stats\">\n        <div><span>Analyzed turns</span><b id=\"report-turns\">0</b></div>\n        <div><span>Language signal</span><b id=\"report-score\">—</b></div>\n        <div><span>New memory cards</span><b id=\"report-cards\">0</b></div>\n        <div><span>XP earned</span><b id=\"report-xp\">0</b></div>\n      </div>\n      <div class=\"report-actions\"><button class=\"button primary\" id=\"restart-button\" type=\"button\">Start another session</button><a class=\"button quiet\" href=\"#report-card\">Open learning memory</a></div>\n    </section>\n\n    <section class=\"architecture-note\" aria-label=\"How the system works\">\n      <p><b>One experience, two clear jobs.</b> Tavus handles presence, perception, and human turn-taking. Fluent Me handles evidence, spaced repetition, and the private cloned-voice correction loop.</p>\n      <div><span>Phoenix · face</span><span>Raven · context</span><span>Sparrow · turns</span><span>Fluent Me · learning memory</span></div>\n    </section>\n  </main>\n\n  <dialog class=\"connection-dialog\" id=\"connection-dialog\">\n    <button class=\"dialog-close\" id=\"dialog-close\" type=\"button\" aria-label=\"Close\">×</button>\n    <p class=\"eyebrow\">Server-side connection</p>\n    <h2>Live mode uses a private Tavus room.</h2>\n    <p>The browser never sees your Tavus API key. Put a newly rotated key in the server environment, then restart Fluent Me. A PAL and stock Face can be selected automatically, or you can choose existing IDs.</p>\n    <pre><code>TAVUS_API_KEY=your_new_key\nTAVUS_PAL_ID=optional_existing_pal\nTAVUS_FACE_ID=optional_existing_face\nELEVENLABS_API_KEY=optional_for_your_mirror_voice</code></pre>\n    <div class=\"dialog-points\">\n      <p><b>Live face + voice</b><span>The Tavus Face supplies Kai’s appearance and default voice.</span></p>\n      <p><b>Your voice clone</b><span>ElevenLabs stays on the private Mirror card; Kai’s face never impersonates you.</span></p>\n      <p><b>Perception</b><span>Raven observations are shown as uncertain context and excluded from scores.</span></p>\n    </div>\n    <button class=\"button primary\" id=\"dialog-done\" type=\"button\">Got it</button>\n  </dialog>\n\n  <script src=\"/static/live.js\" defer></script>\n</body>\n</html>\n";
const CSS = ":root {\n  --paper: #f3f0e8;\n  --paper-2: #ebe6da;\n  --card: #faf8f2;\n  --ink: #17211c;\n  --muted: #69726b;\n  --line: #d7d2c6;\n  --forest: #163f31;\n  --forest-2: #0e2a21;\n  --mint: #b7e0c8;\n  --leaf: #39765e;\n  --coral: #ee6a4b;\n  --amber: #d99a38;\n  --white: #fffdf8;\n  --shadow: 0 24px 70px rgba(35, 42, 37, .11);\n  --sans: \"Aptos\", \"Segoe UI Variable\", \"Segoe UI\", system-ui, sans-serif;\n  --serif: \"Iowan Old Style\", \"Baskerville\", \"Times New Roman\", serif;\n}\n\n* { box-sizing: border-box; }\n[hidden] { display: none !important; }\nhtml { color-scheme: light; scroll-behavior: smooth; }\nbody {\n  margin: 0;\n  min-height: 100vh;\n  color: var(--ink);\n  background: var(--paper);\n  font-family: var(--sans);\n  -webkit-font-smoothing: antialiased;\n}\nbutton, input { font: inherit; }\nbutton, a { -webkit-tap-highlight-color: transparent; }\nbutton:focus-visible, a:focus-visible, input:focus-visible {\n  outline: 3px solid rgba(57, 118, 94, .28);\n  outline-offset: 3px;\n}\na { color: inherit; text-decoration: none; }\n\n.topbar {\n  width: min(1460px, 100%);\n  min-height: 70px;\n  margin: 0 auto;\n  padding: 0 30px;\n  display: flex;\n  align-items: center;\n  gap: 34px;\n  border-bottom: 1px solid rgba(23, 33, 28, .12);\n}\n.brand { display: inline-flex; align-items: center; gap: 11px; font-size: 16px; font-weight: 760; letter-spacing: -.02em; }\n.brand-mark { display: inline-flex; height: 21px; align-items: end; gap: 3px; }\n.brand-mark i { display: block; width: 3px; border-radius: 2px; background: var(--forest); }\n.brand-mark i:nth-child(1) { height: 10px; }\n.brand-mark i:nth-child(2) { height: 20px; }\n.brand-mark i:nth-child(3) { height: 15px; }\n.primary-nav { display: flex; align-items: center; gap: 7px; }\n.primary-nav a { padding: 9px 12px; border-radius: 7px; color: var(--muted); font-size: 13px; font-weight: 620; }\n.primary-nav a:hover { background: rgba(255,255,255,.45); color: var(--ink); }\n.primary-nav a.active { color: var(--forest); background: rgba(57, 118, 94, .09); }\n.connection-pill {\n  margin-left: auto;\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 12px;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  color: var(--muted);\n  background: rgba(250, 248, 242, .72);\n  font-size: 12px;\n  cursor: pointer;\n}\n.status-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 0 4px rgba(217,154,56,.13); }\nbody[data-live-ready=\"true\"] .status-dot { background: var(--leaf); box-shadow: 0 0 0 4px rgba(57,118,94,.13); }\n\n.page-shell { width: min(1400px, calc(100% - 48px)); margin: 0 auto; padding: 52px 0 70px; }\n.intro { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 46px; margin: 0 4px 30px; }\n.eyebrow { margin: 0 0 10px; color: var(--leaf); font-size: 11px; font-weight: 780; letter-spacing: .16em; text-transform: uppercase; }\n.eyebrow span { color: var(--coral); padding: 0 3px; }\n.intro h1 { margin: 0; max-width: 780px; font-family: var(--serif); font-size: clamp(42px, 5vw, 72px); font-weight: 500; line-height: .98; letter-spacing: -.045em; }\n.lede { max-width: 710px; margin: 18px 0 0; color: var(--muted); font-size: 16px; line-height: 1.55; }\n.focus-picker { max-width: 470px; display: flex; justify-content: flex-end; align-items: center; gap: 6px; flex-wrap: wrap; }\n.focus-picker > span { width: 100%; margin: 0 3px 4px; color: var(--muted); font-size: 11px; text-align: right; text-transform: uppercase; letter-spacing: .1em; }\n.focus-chip { padding: 8px 11px; border: 1px solid var(--line); border-radius: 999px; background: transparent; color: var(--muted); font-size: 12px; cursor: pointer; }\n.focus-chip:hover { border-color: #aaa99f; color: var(--ink); }\n.focus-chip.selected { border-color: var(--forest); background: var(--forest); color: var(--white); }\n\n.room-grid { display: grid; grid-template-columns: minmax(0, 1fr) 370px; gap: 18px; align-items: start; }\n.stage-card, .rail-card, .transcript-card, .report-card {\n  border: 1px solid var(--line);\n  background: var(--card);\n  box-shadow: 0 1px 0 rgba(255,255,255,.7) inset;\n}\n.stage-card { min-width: 0; border-radius: 18px; overflow: hidden; box-shadow: var(--shadow); }\n.stage-head { min-height: 60px; padding: 12px 17px 12px 20px; display: flex; align-items: center; justify-content: space-between; gap: 16px; }\n.stage-head > div:first-child { display: flex; align-items: baseline; gap: 11px; min-width: 0; }\n.stage-kicker { color: var(--ink); font-size: 13px; font-weight: 730; }\n.stage-state { color: var(--muted); font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.live-clock { display: flex; align-items: center; gap: 7px; color: var(--forest); font-size: 11px; font-weight: 750; letter-spacing: .04em; text-transform: uppercase; }\n.live-clock i { width: 7px; height: 7px; border-radius: 50%; background: var(--coral); animation: livePulse 1.5s ease-in-out infinite; }\n.live-clock time { min-width: 38px; color: var(--muted); font-variant-numeric: tabular-nums; font-weight: 650; }\n@keyframes livePulse { 50% { opacity: .35; transform: scale(.8); } }\n\n.video-stage {\n  position: relative;\n  min-height: 560px;\n  aspect-ratio: 16 / 10;\n  overflow: hidden;\n  background: var(--forest-2);\n  color: var(--white);\n  isolation: isolate;\n}\n.stage-glow {\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  background:\n    radial-gradient(circle at 72% 36%, rgba(183,224,200,.17), transparent 28%),\n    radial-gradient(circle at 18% 92%, rgba(238,106,75,.12), transparent 25%);\n}\n.video-stage::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  opacity: .1;\n  background-image: repeating-linear-gradient(0deg, transparent 0 5px, rgba(255,255,255,.08) 6px);\n  pointer-events: none;\n}\n.video-stage iframe { position: absolute !important; inset: 0; width: 100% !important; height: 100% !important; border: 0 !important; z-index: 3; background: #08130f; }\n.preview-label { position: absolute; z-index: 7; top: 18px; left: 18px; padding: 7px 10px; border: 1px solid rgba(255,255,255,.19); border-radius: 999px; background: rgba(9,27,21,.72); color: rgba(255,255,255,.78); backdrop-filter: blur(10px); font-size: 10px; letter-spacing: .09em; text-transform: uppercase; }\n.daily-mounted .preview-label, .daily-mounted .stage-placeholder { display: none; }\n.stage-placeholder { min-height: inherit; height: 100%; padding: 56px clamp(28px, 5vw, 76px) 38px; display: grid; grid-template-columns: minmax(210px, .72fr) minmax(280px, 1fr); grid-template-rows: 1fr auto auto; align-items: center; gap: 25px 54px; }\n.signal-portrait { position: relative; width: min(29vw, 320px); aspect-ratio: 1; display: grid; place-items: center; justify-self: center; }\n.portrait-core { position: relative; width: 46%; aspect-ratio: 1; display: grid; place-items: center; border: 1px solid rgba(255,255,255,.35); border-radius: 50%; background: rgba(183,224,200,.1); box-shadow: 0 0 70px rgba(183,224,200,.13); }\n.portrait-core span { font-family: var(--serif); font-size: clamp(46px, 6vw, 86px); font-weight: 400; color: var(--mint); }\n.portrait-core b { position: absolute; bottom: 16%; width: 22%; height: 2px; background: var(--coral); animation: voiceLine 1.8s ease-in-out infinite; }\n.orbit { position: absolute; border: 1px solid rgba(183,224,200,.24); border-radius: 50%; animation: orbit 16s linear infinite; }\n.orbit::before, .orbit::after { content: \"\"; position: absolute; width: 7px; height: 7px; border-radius: 50%; background: var(--mint); }\n.orbit-one { inset: 13%; }\n.orbit-one::before { top: 8%; left: 22%; }\n.orbit-one::after { right: 5%; bottom: 31%; background: var(--coral); }\n.orbit-two { inset: 2%; border-style: dashed; opacity: .55; animation-direction: reverse; animation-duration: 25s; }\n.orbit-two::before { left: 9%; bottom: 20%; }\n.orbit-two::after { right: 20%; top: 6%; }\n@keyframes orbit { to { transform: rotate(360deg); } }\n@keyframes voiceLine { 50% { width: 37%; opacity: .55; } }\n.stage-copy { align-self: end; max-width: 490px; }\n.stage-copy-kicker { margin: 0 0 8px; color: var(--mint); font-size: 11px; font-weight: 750; text-transform: uppercase; letter-spacing: .12em; }\n.stage-copy h2 { margin: 0; font-family: var(--serif); font-size: clamp(30px, 3.2vw, 48px); font-weight: 500; line-height: 1.02; letter-spacing: -.035em; }\n.stage-copy > p:last-child { margin: 15px 0 0; max-width: 480px; color: rgba(255,255,255,.68); font-size: 13px; line-height: 1.55; }\n.camera-choice { grid-column: 2; align-self: start; display: flex; align-items: flex-start; gap: 10px; color: rgba(255,255,255,.76); cursor: pointer; }\n.camera-choice input { width: 17px; height: 17px; margin: 2px 0 0; accent-color: var(--mint); }\n.camera-choice span { display: grid; gap: 2px; }\n.camera-choice b { font-size: 12px; color: var(--white); }\n.camera-choice small { font-size: 11px; line-height: 1.4; }\n.stage-actions { grid-column: 2; display: flex; align-items: center; gap: 9px; flex-wrap: wrap; }\n.button { min-height: 42px; display: inline-flex; align-items: center; justify-content: center; padding: 0 17px; border: 1px solid transparent; border-radius: 8px; font-size: 12px; font-weight: 740; cursor: pointer; }\n.button.primary { color: var(--white); background: var(--coral); border-color: var(--coral); box-shadow: 0 8px 24px rgba(238,106,75,.2); }\n.button.primary:hover { background: #d95a3c; }\n.button.primary:disabled { opacity: .5; cursor: wait; }\n.button.quiet { color: inherit; background: transparent; border-color: currentColor; opacity: .74; }\n.button.quiet:hover { opacity: 1; }\n.stage-actions .button.quiet { color: rgba(255,255,255,.82); }\n.speaking-cue { position: absolute; z-index: 8; left: 50%; bottom: 20px; transform: translateX(-50%); display: flex; align-items: center; gap: 8px; padding: 8px 11px; border: 1px solid rgba(255,255,255,.16); border-radius: 999px; background: rgba(8,24,18,.78); backdrop-filter: blur(10px); color: var(--white); font-size: 11px; }\n.speaking-cue span { width: 9px; height: 9px; border-radius: 50%; border: 2px solid var(--mint); animation: cue 1s ease-out infinite; }\n@keyframes cue { 80%, 100% { box-shadow: 0 0 0 8px transparent; border-color: var(--coral); } }\n\n.stage-controls { min-height: 52px; padding: 9px 14px 9px 20px; display: flex; align-items: center; justify-content: space-between; gap: 14px; border-bottom: 1px solid var(--line); }\n.stage-controls p { margin: 0; color: var(--muted); font-size: 11px; }\n.stage-controls > div { display: flex; gap: 8px; }\n.control-button { padding: 7px 10px; border: 1px solid var(--line); border-radius: 7px; background: transparent; color: var(--muted); font-size: 11px; cursor: pointer; }\n.control-button:hover { color: var(--ink); border-color: #aaa99f; }\n.control-button.danger { color: #a94432; }\n\n.perception-ribbon { min-height: 108px; display: grid; grid-template-columns: 1.02fr 1fr 1fr; }\n.ribbon-intro, .signal-card { min-width: 0; padding: 17px 19px; }\n.ribbon-intro { display: flex; align-items: flex-start; gap: 11px; background: rgba(57,118,94,.055); }\n.signal-icon { flex: none; width: 25px; height: 25px; display: grid; place-items: center; border-radius: 50%; background: var(--forest); color: var(--mint); font-family: var(--serif); font-size: 13px; }\n.ribbon-intro div { display: grid; gap: 4px; }\n.ribbon-intro b { font-size: 12px; }\n.ribbon-intro small { color: var(--muted); font-size: 10.5px; line-height: 1.4; }\n.signal-card { border-left: 1px solid var(--line); }\n.signal-card span { color: var(--leaf); font-size: 9px; font-weight: 780; letter-spacing: .11em; text-transform: uppercase; }\n.signal-card p { margin: 7px 0 0; color: var(--muted); font-size: 11px; line-height: 1.4; }\n\n.coach-rail { display: grid; gap: 12px; }\n.rail-card { min-width: 0; padding: 18px; border-radius: 13px; }\n.rail-card > header { display: flex; align-items: flex-start; gap: 11px; }\n.rail-index { flex: none; width: 25px; height: 25px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%; color: var(--muted); font-size: 9px; font-variant-numeric: tabular-nums; }\n.rail-kicker { margin: 0 0 3px; color: var(--leaf); font-size: 9px; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; }\n.rail-card h2, .transcript-card h2, .report-card h2 { margin: 0; font-family: var(--serif); font-size: 21px; font-weight: 500; letter-spacing: -.02em; }\n.rail-explain { margin: 14px 0 12px; color: var(--muted); font-size: 11.5px; line-height: 1.5; }\n.memory-targets { display: flex; flex-wrap: wrap; gap: 7px; }\n.memory-target { max-width: 100%; padding: 6px 9px; border: 1px solid rgba(57,118,94,.25); border-radius: 999px; background: rgba(57,118,94,.06); color: var(--forest); font-size: 10px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.memory-target.empty { border-style: dashed; color: var(--muted); background: transparent; }\n.target-skeleton { width: 132px; height: 25px; border-radius: 999px; background: var(--paper-2); animation: skeleton 1.4s ease-in-out infinite; }\n.target-skeleton.short { width: 92px; }\n@keyframes skeleton { 50% { opacity: .45; } }\n.score-summary { display: grid; grid-template-columns: 62px 1fr; align-items: center; gap: 11px; margin: 18px 0 15px; }\n.score-summary > strong { font-family: var(--serif); font-size: 50px; font-weight: 500; line-height: 1; letter-spacing: -.05em; }\n.score-summary > span { display: grid; gap: 3px; }\n.score-summary b { font-size: 11px; }\n.score-summary small { color: var(--muted); font-size: 9.5px; line-height: 1.35; }\n.score-grid { display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid var(--line); border-left: 1px solid var(--line); }\n.score-grid > div { position: relative; min-height: 65px; padding: 10px; display: grid; grid-template-columns: 1fr auto; align-content: start; gap: 6px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }\n.score-grid span { color: var(--muted); font-size: 9px; text-transform: uppercase; letter-spacing: .08em; }\n.score-grid b { font-size: 14px; font-variant-numeric: tabular-nums; }\n.score-grid i { grid-column: 1 / -1; height: 3px; border-radius: 3px; overflow: hidden; background: var(--paper-2); }\n.score-grid em { display: block; width: 0; height: 100%; border-radius: inherit; background: var(--leaf); transition: width .5s ease; }\n.score-grid .unavailable { align-content: center; }\n.score-grid .unavailable b { color: #9ca19d; }\n.score-grid .unavailable small { grid-column: 1 / -1; color: #9ca19d; font-size: 9px; }\n.mirror-card { overflow: hidden; }\n.mirror-empty { min-height: 112px; margin-top: 14px; display: grid; place-items: center; align-content: center; gap: 11px; border: 1px dashed var(--line); background: rgba(235,230,218,.3); }\n.mirror-empty p { max-width: 275px; margin: 0; color: var(--muted); font-size: 10.5px; line-height: 1.45; text-align: center; }\n.mirror-wave { height: 21px; display: flex; align-items: center; gap: 3px; }\n.mirror-wave i { width: 2px; height: 7px; border-radius: 2px; background: var(--leaf); }\n.mirror-wave i:nth-child(2), .mirror-wave i:nth-child(6) { height: 13px; }\n.mirror-wave i:nth-child(3), .mirror-wave i:nth-child(5) { height: 20px; }\n.mirror-wave i:nth-child(4) { height: 10px; }\n.mirror-result { margin-top: 14px; }\n.before-label, .after-label { display: block; margin-top: 9px; color: var(--muted); font-size: 8.5px; font-weight: 780; letter-spacing: .12em; text-transform: uppercase; }\n.before-text { margin: 4px 0 0; color: var(--muted); font-size: 11px; line-height: 1.4; text-decoration: line-through; text-decoration-color: rgba(238,106,75,.55); }\n.mirror-result blockquote { margin: 5px 0 14px; padding: 0; border: 0; font-family: var(--serif); font-size: 20px; line-height: 1.26; }\n.mirror-play { width: 100%; min-height: 51px; padding: 8px 10px; display: grid; grid-template-columns: 28px 1fr; grid-template-rows: auto auto; align-items: center; column-gap: 8px; border: 1px solid var(--forest); border-radius: 8px; background: var(--forest); color: var(--white); cursor: pointer; text-align: left; }\n.mirror-play > span { grid-row: 1 / 3; width: 28px; height: 28px; display: grid; place-items: center; border-radius: 50%; background: var(--mint); color: var(--forest); font-size: 9px; }\n.mirror-play b { align-self: end; font-size: 11px; }\n.mirror-play small { align-self: start; color: rgba(255,255,255,.62); font-size: 9px; }\n.mirror-play:disabled { cursor: not-allowed; opacity: .72; }\n\n.transcript-card { margin-top: 18px; padding: 24px 26px; border-radius: 14px; }\n.transcript-card > header { display: flex; justify-content: space-between; align-items: end; gap: 16px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }\n.transcript-card > header > span { color: var(--muted); font-size: 10px; }\n.transcript { min-height: 130px; max-height: 430px; overflow-y: auto; }\n.transcript-empty { min-height: 128px; display: flex; align-items: center; justify-content: center; gap: 13px; color: var(--muted); }\n.transcript-empty > span { font-family: var(--serif); font-size: 44px; color: var(--line); }\n.transcript-empty p { max-width: 530px; margin: 0; font-family: var(--serif); font-size: 16px; line-height: 1.45; }\n.transcript-turn { display: grid; grid-template-columns: 88px minmax(0, 1fr) auto; gap: 14px; align-items: start; padding: 14px 0; border-bottom: 1px solid rgba(215,210,198,.68); }\n.transcript-turn:last-child { border-bottom: 0; }\n.transcript-speaker { display: flex; align-items: center; gap: 7px; color: var(--muted); font-size: 10px; font-weight: 750; text-transform: uppercase; letter-spacing: .08em; }\n.transcript-speaker i { width: 7px; height: 7px; border-radius: 50%; background: var(--leaf); }\n.transcript-turn.user .transcript-speaker i { background: var(--coral); }\n.transcript-text { margin: 0; font-size: 13px; line-height: 1.55; overflow-wrap: anywhere; }\n.transcript-meta { color: var(--muted); font-size: 9px; white-space: nowrap; }\n\n.report-card { margin-top: 18px; padding: 30px; border-radius: 14px; background: var(--forest); color: var(--white); }\n.report-card .eyebrow { color: var(--mint); }\n.report-heading { max-width: 700px; }\n.report-heading h2 { font-size: 31px; }\n.report-heading > p:last-child { margin: 10px 0 0; color: rgba(255,255,255,.65); font-size: 13px; line-height: 1.5; }\n.report-stats { margin: 26px 0; display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid rgba(255,255,255,.16); border-left: 1px solid rgba(255,255,255,.16); }\n.report-stats > div { min-height: 88px; padding: 15px; display: grid; align-content: space-between; border-right: 1px solid rgba(255,255,255,.16); border-bottom: 1px solid rgba(255,255,255,.16); }\n.report-stats span { color: rgba(255,255,255,.55); font-size: 9px; text-transform: uppercase; letter-spacing: .1em; }\n.report-stats b { font-family: var(--serif); font-size: 30px; font-weight: 500; }\n.report-actions { display: flex; gap: 9px; flex-wrap: wrap; }\n.report-actions .button.quiet { color: var(--white); }\n\n.architecture-note { margin: 29px 4px 0; padding-top: 22px; display: flex; justify-content: space-between; gap: 24px; border-top: 1px solid var(--line); color: var(--muted); }\n.architecture-note p { max-width: 740px; margin: 0; font-size: 12px; line-height: 1.5; }\n.architecture-note p b { color: var(--ink); }\n.architecture-note div { display: flex; justify-content: flex-end; align-items: flex-start; gap: 6px; flex-wrap: wrap; }\n.architecture-note span { padding: 5px 8px; border: 1px solid var(--line); border-radius: 999px; font-size: 9px; white-space: nowrap; }\n\n.connection-dialog { width: min(620px, calc(100% - 30px)); padding: 33px; border: 1px solid rgba(255,255,255,.16); border-radius: 16px; background: var(--forest-2); color: var(--white); box-shadow: 0 35px 100px rgba(0,0,0,.35); }\n.connection-dialog::backdrop { background: rgba(15,25,20,.58); backdrop-filter: blur(5px); }\n.connection-dialog h2 { max-width: 500px; margin: 0; font-family: var(--serif); font-size: 32px; font-weight: 500; line-height: 1.05; }\n.connection-dialog > p:not(.eyebrow) { color: rgba(255,255,255,.67); font-size: 13px; line-height: 1.55; }\n.connection-dialog pre { margin: 20px 0; padding: 15px; overflow-x: auto; border: 1px solid rgba(255,255,255,.15); border-radius: 8px; background: rgba(255,255,255,.05); color: var(--mint); font: 11px/1.7 ui-monospace, \"SFMono-Regular\", Consolas, monospace; }\n.dialog-close { position: absolute; top: 14px; right: 16px; border: 0; background: transparent; color: rgba(255,255,255,.6); font-size: 25px; cursor: pointer; }\n.dialog-points { margin: 0 0 22px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: rgba(255,255,255,.13); border: 1px solid rgba(255,255,255,.13); }\n.dialog-points p { margin: 0; padding: 12px; display: grid; gap: 5px; background: var(--forest-2); }\n.dialog-points b { font-size: 10px; }\n.dialog-points span { color: rgba(255,255,255,.55); font-size: 9.5px; line-height: 1.4; }\n\nbody[data-room-state=\"joining\"] .signal-portrait { animation: joining 1.8s ease-in-out infinite; }\nbody[data-room-state=\"live\"] .portrait-core b,\nbody[data-room-state=\"preview\"] .portrait-core b { animation-duration: .65s; }\n@keyframes joining { 50% { opacity: .56; transform: scale(.97); } }\n\n@media (max-width: 1120px) {\n  .intro { grid-template-columns: 1fr; gap: 24px; }\n  .focus-picker { justify-content: flex-start; max-width: none; }\n  .focus-picker > span { text-align: left; }\n  .room-grid { grid-template-columns: 1fr; }\n  .coach-rail { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n  .video-stage { min-height: 500px; }\n}\n\n@media (max-width: 820px) {\n  .topbar { padding: 0 18px; gap: 12px; }\n  .primary-nav a { display: none; }\n  .primary-nav a.active { display: block; }\n  .connection-pill { padding: 8px 9px; }\n  .page-shell { width: min(100% - 24px, 720px); padding-top: 34px; }\n  .intro h1 { font-size: clamp(41px, 12vw, 62px); }\n  .lede { font-size: 14px; }\n  .stage-placeholder { padding: 56px 28px 30px; grid-template-columns: 1fr; grid-template-rows: auto auto auto auto; gap: 18px; text-align: center; }\n  .signal-portrait { width: 200px; }\n  .stage-copy { align-self: auto; justify-self: center; }\n  .camera-choice, .stage-actions { grid-column: 1; justify-self: center; }\n  .camera-choice { text-align: left; }\n  .video-stage { min-height: 620px; aspect-ratio: auto; }\n  .perception-ribbon { grid-template-columns: 1fr 1fr; }\n  .ribbon-intro { grid-column: 1 / -1; }\n  .signal-card:nth-child(2) { border-left: 0; }\n  .coach-rail { grid-template-columns: 1fr; }\n  .rail-card { padding: 20px; }\n  .architecture-note { flex-direction: column; }\n  .architecture-note div { justify-content: flex-start; }\n  .dialog-points { grid-template-columns: 1fr; }\n}\n\n@media (max-width: 540px) {\n  .topbar { min-height: 62px; }\n  .brand { font-size: 14px; }\n  .primary-nav { display: none; }\n  .connection-pill { max-width: 152px; }\n  #connection-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .page-shell { width: 100%; padding: 27px 10px calc(50px + env(safe-area-inset-bottom)); }\n  .intro { margin: 0 8px 23px; }\n  .intro h1 { font-size: 42px; }\n  .focus-picker { flex-wrap: nowrap; overflow-x: auto; padding-bottom: 3px; justify-content: flex-start; }\n  .focus-picker > span { display: none; }\n  .focus-chip { flex: none; }\n  .stage-card { border-radius: 12px; }\n  .stage-head { min-height: 52px; }\n  .stage-state { display: none; }\n  .video-stage { min-height: 61dvh; max-height: 670px; }\n  .stage-placeholder { padding: 43px 20px 24px; }\n  .signal-portrait { width: 165px; }\n  .stage-copy h2 { font-size: 31px; }\n  .stage-copy > p:last-child { font-size: 12px; }\n  .stage-actions { width: 100%; }\n  .stage-actions .button { flex: 1; }\n  .stage-controls { position: sticky; bottom: env(safe-area-inset-bottom); z-index: 10; background: var(--card); }\n  .stage-controls p { display: none; }\n  .stage-controls > div { margin-left: auto; }\n  .perception-ribbon { grid-template-columns: 1fr; }\n  .ribbon-intro { grid-column: auto; }\n  .signal-card { border-left: 0; border-top: 1px solid var(--line); }\n  .transcript-card { padding: 20px 17px; border-radius: 12px; }\n  .transcript-turn { grid-template-columns: 70px 1fr; }\n  .transcript-meta { grid-column: 2; }\n  .report-card { padding: 24px 18px; }\n  .report-stats { grid-template-columns: 1fr 1fr; }\n  .connection-dialog { padding: 28px 20px 22px; }\n  .connection-dialog h2 { font-size: 28px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }\n}\n";
const JS = "(() => {\n  \"use strict\";\n\n  const $ = id => document.getElementById(id);\n  const state = {\n    mode: \"booting\",\n    configured: false,\n    focus: \"conversation\",\n    call: null,\n    conversationId: null,\n    startedAt: 0,\n    timerId: null,\n    reportId: null,\n    transcriptCount: 0,\n    seenEvents: new Set(),\n    currentAudio: null,\n    mirrorAudio: null,\n    ending: false,\n  };\n\n  const SAMPLE = {\n    user: \"Last weekend I go to a networking event and I meet a founder.\",\n    pal: \"That sounds like a useful event. What did you two end up talking about?\",\n    audio: \"Delivery became more tentative around the past-tense phrase.\",\n    visual: \"The learner is facing the screen; no relevant object is being shown.\",\n    scores: { composite: 68, dims: { grammar: 58, vocab: 82, fluency: null, pron: null } },\n    mirror: \"Last weekend I went to a networking event and met a founder.\",\n    errors: [\"past tense\"],\n  };\n\n  function setRoomState(next, label) {\n    state.mode = next;\n    document.body.dataset.roomState = next;\n    if (label) $(\"stage-state\").textContent = label;\n  }\n\n  function setText(id, value) {\n    $(id).textContent = value == null ? \"\" : String(value);\n  }\n\n  function formatTime(totalSeconds) {\n    const s = Math.max(0, Math.floor(totalSeconds));\n    return `${String(Math.floor(s / 60)).padStart(2, \"0\")}:${String(s % 60).padStart(2, \"0\")}`;\n  }\n\n  function beginClock() {\n    state.startedAt = Date.now();\n    $(\"live-clock\").hidden = false;\n    clearInterval(state.timerId);\n    state.timerId = setInterval(() => setText(\"timer\", formatTime((Date.now() - state.startedAt) / 1000)), 1000);\n  }\n\n  function stopClock() {\n    clearInterval(state.timerId);\n    state.timerId = null;\n    $(\"live-clock\").hidden = true;\n  }\n\n  function setStartButton(label, disabled = false) {\n    setText(\"start-button\", label);\n    $(\"start-button\").disabled = disabled;\n  }\n\n  async function fetchJSON(url, options = {}) {\n    const response = await fetch(url, {\n      ...options,\n      headers: { \"content-type\": \"application/json\", ...(options.headers || {}) },\n    });\n    let body = {};\n    try { body = await response.json(); } catch {}\n    if (!response.ok) {\n      const error = new Error(body.error || `Request failed (${response.status})`);\n      error.reason = body.reason;\n      error.status = response.status;\n      throw error;\n    }\n    return body;\n  }\n\n  function textNode(tag, className, text) {\n    const node = document.createElement(tag);\n    if (className) node.className = className;\n    node.textContent = text;\n    return node;\n  }\n\n  function renderMemoryTargets(data) {\n    const root = $(\"memory-targets\");\n    root.replaceChildren();\n    const patterns = Array.isArray(data) ? data.filter(Boolean).slice(0, 3) : [];\n    if (!patterns.length) {\n      root.append(textNode(\"span\", \"memory-target empty\", \"No due patterns — open conversation today\"));\n      return;\n    }\n    patterns.forEach(pattern => root.append(textNode(\"span\", \"memory-target\", pattern.replaceAll(\"-\", \" \"))));\n  }\n\n  async function loadLearningState() {\n    try {\n      const profile = await fetchJSON(\"/api/cards\", { headers: {} });\n      const now = Number(profile.now || Date.now() / 1000);\n      const due = (profile.cards || [])\n        .filter(card => card.status === \"learning\" && Number(card.due_at || 0) <= now)\n        .map(card => card.label || card.pattern);\n      renderMemoryTargets(due);\n    } catch {\n      renderMemoryTargets([]);\n    }\n  }\n\n  function updateConnectionUI() {\n    document.body.dataset.liveReady = state.configured ? \"true\" : \"false\";\n    setText(\"connection-label\", state.configured ? \"Tavus ready\" : \"Preview · Tavus not connected\");\n    $(\"preview-label\").textContent = state.configured ? \"Private room · camera optional\" : \"Preview mode · sample signals\";\n    if (state.configured) {\n      setStartButton(\"Start live session\");\n      setText(\"stage-copy-kicker\", \"Private Tavus room\");\n      setText(\"stage-title\", \"Step into a real conversation with Kai.\");\n      setText(\"stage-description\", \"Raven supplies live context, Sparrow manages turns, and Fluent Me learns beside the call.\");\n      setRoomState(\"ready\", \"Ready for a private session\");\n    } else {\n      setStartButton(\"Enter guided preview\");\n      setText(\"stage-copy-kicker\", \"Interactive product preview\");\n      setText(\"stage-title\", \"See how perception becomes useful—not performative.\");\n      setText(\"stage-description\", \"This preview uses clearly labelled sample observations. Add a fresh server-side Tavus key for a real call.\");\n      setRoomState(\"ready\", \"Preview available\");\n    }\n  }\n\n  async function boot() {\n    await loadLearningState();\n    try {\n      const status = await fetchJSON(\"/api/tavus/status\", { headers: {} });\n      state.configured = Boolean(status.configured);\n    } catch {\n      state.configured = false;\n    }\n    updateConnectionUI();\n  }\n\n  function chooseFocus(button) {\n    document.querySelectorAll(\".focus-chip\").forEach(chip => chip.classList.toggle(\"selected\", chip === button));\n    state.focus = button.dataset.focus;\n  }\n\n  function resetSignals() {\n    setText(\"audio-perception\", \"Waiting for a complete user turn.\");\n    setText(\"visual-perception\", $(\"camera-enabled\").checked\n      ? \"Camera context will appear here when available.\"\n      : \"Camera is off. Visual context is not being collected.\");\n  }\n\n  function setSpeaking(role, active) {\n    if (!active) {\n      $(\"speaking-cue\").hidden = true;\n      if (state.mode === \"live\") setText(\"stage-state\", \"Listening for the next turn\");\n      return;\n    }\n    const user = role === \"user\";\n    setText(\"speaking-label\", user ? \"You are speaking\" : \"Kai is speaking\");\n    setText(\"stage-state\", user ? \"Listening\" : \"Kai is responding\");\n    $(\"speaking-cue\").hidden = false;\n  }\n\n  function appendTranscript(role, speech, meta = \"\") {\n    if (!speech) return;\n    $(\"transcript-empty\").hidden = true;\n    const row = document.createElement(\"article\");\n    row.className = `transcript-turn ${role === \"user\" ? \"user\" : \"pal\"}`;\n    const who = document.createElement(\"span\");\n    who.className = \"transcript-speaker\";\n    who.append(document.createElement(\"i\"), document.createTextNode(role === \"user\" ? \"You\" : \"Kai\"));\n    row.append(who, textNode(\"p\", \"transcript-text\", speech),\n      textNode(\"span\", \"transcript-meta\", meta || formatTime((Date.now() - state.startedAt) / 1000)));\n    $(\"transcript\").append(row);\n    state.transcriptCount += 1;\n    setText(\"transcript-count\", `${state.transcriptCount} utterance${state.transcriptCount === 1 ? \"\" : \"s\"}`);\n    row.scrollIntoView({ block: \"nearest\", behavior: \"smooth\" });\n  }\n\n  function setScoreValue(name, value) {\n    setText(`score-${name}`, value == null ? \"n/a\" : Math.round(value));\n    const bar = $(`bar-${name}`);\n    if (bar) bar.style.width = `${value == null ? 0 : Math.max(0, Math.min(100, value))}%`;\n  }\n\n  function renderScores(scores, degraded = false) {\n    const dims = scores?.dims || {};\n    setText(\"turn-score\", scores?.composite == null ? \"—\" : Math.round(scores.composite));\n    setText(\"score-caption\", degraded ? \"Coach analysis unavailable\" : \"Latest language evidence\");\n    setText(\"score-note\", \"Grammar and vocabulary only. Raven context is excluded from grading.\");\n    setScoreValue(\"grammar\", dims.grammar);\n    setScoreValue(\"vocab\", dims.vocab);\n    setScoreValue(\"fluency\", null);\n    setScoreValue(\"pron\", null);\n  }\n\n  function stopMirrorAudio() {\n    if (state.currentAudio) {\n      state.currentAudio.pause();\n      state.currentAudio = null;\n    }\n    setText(\"mirror-play\", \"\");\n  }\n\n  function renderMirror(before, after, audioUrl, engine, ownVoice) {\n    $(\"mirror-empty\").hidden = true;\n    $(\"mirror-result\").hidden = false;\n    setText(\"mirror-before\", before);\n    setText(\"mirror-after\", after || before);\n    state.mirrorAudio = audioUrl || null;\n    const button = $(\"mirror-play\");\n    button.disabled = !audioUrl;\n    button.replaceChildren();\n    button.append(textNode(\"span\", \"\", audioUrl ? \"▶\" : \"·\"));\n    const label = textNode(\"b\", \"\", audioUrl ? \"Hear the fluent me\" : \"Mirror audio unavailable\");\n    const detail = textNode(\"small\", \"\", ownVoice ? \"Your cloned voice\" : (audioUrl ? \"Fallback voice · clone pending\" : \"Add ElevenLabs or local TTS\"));\n    if (engine) detail.title = engine;\n    button.append(label, detail);\n  }\n\n  function playMirror() {\n    if (!state.mirrorAudio) return;\n    if (state.currentAudio) state.currentAudio.pause();\n    const audio = new Audio(state.mirrorAudio);\n    state.currentAudio = audio;\n    const button = $(\"mirror-play\");\n    const icon = button.querySelector(\"span\");\n    if (icon) icon.textContent = \"■\";\n    audio.onended = audio.onerror = () => {\n      if (state.currentAudio === audio) state.currentAudio = null;\n      if (icon) icon.textContent = \"▶\";\n    };\n    audio.play().catch(() => { if (icon) icon.textContent = \"▶\"; });\n  }\n\n  function renderPerception(audio, visual, sample = false) {\n    if (audio) setText(\"audio-perception\", `${sample ? \"Sample · \" : \"\"}${audio}`);\n    if (visual) setText(\"visual-perception\", `${sample ? \"Sample · \" : \"\"}${visual}`);\n  }\n\n  function eventKey(message) {\n    return [message.event_type, message.seq ?? \"\", message.inference_id ?? \"\", message.properties?.role ?? \"\"].join(\":\");\n  }\n\n  function normalizeMessage(event) {\n    const candidate = event?.data || event;\n    if (typeof candidate === \"string\") {\n      try { return JSON.parse(candidate); } catch { return {}; }\n    }\n    return candidate && typeof candidate === \"object\" ? candidate : {};\n  }\n\n  async function sendPalEvent(message) {\n    try {\n      await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/events`, {\n        method: \"POST\", body: JSON.stringify(message),\n      });\n    } catch {}\n  }\n\n  async function analyzeUserTurn(message) {\n    const props = message.properties || {};\n    const speech = String(props.speech || \"\").trim();\n    if (!speech) return;\n    appendTranscript(\"user\", speech);\n    renderPerception(props.user_audio_analysis, props.user_visual_analysis);\n    setText(\"score-caption\", \"Analyzing this turn…\");\n    try {\n      const result = await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/turn`, {\n        method: \"POST\",\n        body: JSON.stringify({\n          speech,\n          seq: message.seq,\n          inference_id: message.inference_id,\n          turn_idx: message.turn_idx,\n          audio_analysis: props.user_audio_analysis || \"\",\n          visual_analysis: props.user_visual_analysis || \"\",\n        }),\n      });\n      if (result.status === \"processing\") return;\n      renderScores(result.scores, result.degraded);\n      if (result.mirror_text) renderMirror(speech, result.mirror_text, result.mirror_audio,\n        result.mirror_engine, result.mirror_own_voice);\n      loadLearningState();\n    } catch (error) {\n      setText(\"score-caption\", \"Turn analysis unavailable\");\n      setText(\"score-note\", error.message);\n    }\n  }\n\n  function handleAppMessage(event) {\n    const message = normalizeMessage(event);\n    if (!message.event_type || (message.conversation_id && message.conversation_id !== state.conversationId)) return;\n    const key = eventKey(message);\n    if (state.seenEvents.has(key)) return;\n    state.seenEvents.add(key);\n    const props = message.properties || {};\n    if (props.role === \"replica\") return;\n\n    if (message.event_type === \"conversation.started_speaking\") {\n      setSpeaking(props.role, true);\n      return;\n    }\n    if (message.event_type === \"conversation.stopped_speaking\") {\n      setSpeaking(props.role, false);\n      return;\n    }\n    if (message.event_type !== \"conversation.utterance\") return;\n    const speech = String(props.speech || \"\").trim();\n    if (props.role === \"user\") analyzeUserTurn(message);\n    if (props.role === \"pal\") {\n      appendTranscript(\"pal\", speech);\n      sendPalEvent(message);\n    }\n  }\n\n  function registerCallHandlers(call) {\n    call.on(\"app-message\", handleAppMessage);\n    call.on(\"joined-meeting\", () => {\n      setRoomState(\"live\", \"Listening for the first turn\");\n      $(\"live-clock\").hidden = false;\n      $(\"end-button\").hidden = false;\n      setText(\"room-note\", \"Live Tavus room · camera optional · microphone on\");\n      beginClock();\n    });\n    call.on(\"left-meeting\", () => { if (!state.ending) endSession(); });\n    call.on(\"error\", event => {\n      setRoomState(\"error\", \"Kai couldn’t join this room\");\n      setText(\"room-note\", event?.errorMsg || \"Retry, or continue in the guided preview.\");\n      setStartButton(\"Retry live session\");\n    });\n  }\n\n  async function startLive() {\n    setRoomState(\"joining\", \"Bringing Kai into the room…\");\n    setStartButton(\"Connecting…\", true);\n    $(\"camera-choice\").style.pointerEvents = \"none\";\n    setText(\"room-note\", \"This usually takes 5–20 seconds.\");\n    resetSignals();\n    try {\n      const room = await fetchJSON(\"/api/tavus/conversations\", {\n        method: \"POST\", body: JSON.stringify({ focus: state.focus }),\n      });\n      state.conversationId = room.conversation_id;\n      const call = window.Daily.createFrame($(\"video-stage\"), {\n        showLeaveButton: false,\n        showFullscreenButton: true,\n        activeSpeakerMode: true,\n        iframeStyle: { width: \"100%\", height: \"100%\", border: \"0\" },\n      });\n      state.call = call;\n      registerCallHandlers(call);\n      $(\"video-stage\").classList.add(\"daily-mounted\");\n      await call.join({\n        url: room.conversation_url,\n        token: room.meeting_token,\n        startVideoOff: !$(\"camera-enabled\").checked,\n      });\n    } catch (error) {\n      state.ending = false;\n      setRoomState(\"error\", \"Kai couldn’t join this room\");\n      setText(\"room-note\", error.message || \"Try again, or enter the guided preview.\");\n      setStartButton(\"Retry live session\");\n      $(\"start-button\").disabled = false;\n      $(\"camera-choice\").style.pointerEvents = \"\";\n      if (error.reason === \"not_configured\" || error.status === 401 || error.status === 403) openConnectionDialog();\n    }\n  }\n\n  function startPreview() {\n    setRoomState(\"preview\", \"Guided preview · sample data\");\n    setStartButton(\"Preview running\", true);\n    $(\"camera-choice\").style.pointerEvents = \"none\";\n    $(\"sample-button\").hidden = false;\n    $(\"end-button\").hidden = false;\n    $(\"live-clock\").hidden = false;\n    setText(\"room-note\", \"Preview mode uses sample signals and does not access your camera or microphone.\");\n    setText(\"stage-copy-kicker\", \"Preview is ready\");\n    setText(\"stage-title\", \"Try one complete learning turn.\");\n    setText(\"stage-description\", \"Press “Run sample turn” below. Every observation and score will remain clearly labelled as sample data.\");\n    $(\"camera-choice\").hidden = true;\n    $(\"stage-actions\").hidden = true;\n    beginClock();\n  }\n\n  async function runSampleTurn() {\n    const button = $(\"sample-button\");\n    button.disabled = true;\n    setSpeaking(\"user\", true);\n    await new Promise(resolve => setTimeout(resolve, 700));\n    appendTranscript(\"user\", SAMPLE.user, \"sample\");\n    setSpeaking(\"user\", false);\n    renderPerception(SAMPLE.audio, SAMPLE.visual, true);\n    setText(\"score-caption\", \"Analyzing sample turn…\");\n    await new Promise(resolve => setTimeout(resolve, 800));\n    renderScores(SAMPLE.scores);\n    renderMirror(SAMPLE.user, SAMPLE.mirror, null, \"Preview only\", false);\n    setSpeaking(\"pal\", true);\n    await new Promise(resolve => setTimeout(resolve, 700));\n    appendTranscript(\"pal\", SAMPLE.pal, \"sample\");\n    setSpeaking(\"pal\", false);\n    renderMemoryTargets([\"tense past simple\", \"concise interview story\"]);\n    setText(\"score-note\", \"Sample grammar and vocabulary evidence. Perception did not affect the score.\");\n    button.textContent = \"Run another sample\";\n    button.disabled = false;\n  }\n\n  async function destroyCall() {\n    if (!state.call) return;\n    const call = state.call;\n    state.call = null;\n    try { await call.leave(); } catch {}\n    try { call.destroy(); } catch {}\n    $(\"video-stage\").classList.remove(\"daily-mounted\");\n  }\n\n  function renderReport(report) {\n    $(\"report-card\").hidden = false;\n    $(\"report-card\").scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n    setText(\"report-turns\", report.turns ?? 0);\n    setText(\"report-score\", report.avg ?? \"—\");\n    setText(\"report-cards\", report.cards_created ?? 0);\n    setText(\"report-xp\", report.xp_gained ?? 0);\n    if (report.status === \"ready\") {\n      setText(\"report-title\", \"Nice work. Your learning memory is updated.\");\n      setText(\"report-summary\", report.summary || \"The session is saved and ready to revisit.\");\n    } else {\n      setText(\"report-title\", \"Nice work. Finalizing your recap…\");\n      setText(\"report-summary\", \"The call has ended; transcript and memory are still being distilled.\");\n    }\n  }\n\n  async function pollReport() {\n    clearTimeout(state.reportId);\n    if (!state.conversationId) return;\n    try {\n      const report = await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/report`, { headers: {} });\n      renderReport(report);\n      if (report.status !== \"ready\") state.reportId = setTimeout(pollReport, 1500);\n    } catch {}\n  }\n\n  function previewReport() {\n    renderReport({ status: \"ready\", turns: 1, avg: 68, cards_created: 1, xp_gained: 14,\n      summary: \"Sample recap: the learner told a recent story and practiced consistent past tense. In a live room, this would now be stored for future conversational review.\" });\n  }\n\n  async function endSession() {\n    if (state.ending || ![\"live\", \"preview\", \"joining\"].includes(state.mode)) return;\n    state.ending = true;\n    setRoomState(\"ending\", \"Ending the session…\");\n    $(\"end-button\").disabled = true;\n    $(\"sample-button\").hidden = true;\n    stopClock();\n    if (state.mode === \"preview\" || !state.conversationId) {\n      previewReport();\n      setRoomState(\"ended\", \"Preview complete\");\n      state.ending = false;\n      return;\n    }\n    await destroyCall();\n    try {\n      const report = await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/end`, {\n        method: \"POST\", body: \"{}\",\n      });\n      renderReport(report);\n      pollReport();\n      setRoomState(\"ended\", \"Session ended · finalizing recap\");\n    } catch (error) {\n      setRoomState(\"error\", \"Call ended; recap needs attention\");\n      setText(\"room-note\", error.message);\n    } finally {\n      state.ending = false;\n    }\n  }\n\n  async function restart() {\n    clearTimeout(state.reportId);\n    await destroyCall();\n    state.conversationId = null;\n    state.ending = false;\n    state.transcriptCount = 0;\n    state.seenEvents.clear();\n    state.mirrorAudio = null;\n    $(\"transcript\").querySelectorAll(\".transcript-turn\").forEach(node => node.remove());\n    $(\"transcript-empty\").hidden = false;\n    setText(\"transcript-count\", \"No turns yet\");\n    $(\"report-card\").hidden = true;\n    $(\"mirror-empty\").hidden = false;\n    $(\"mirror-result\").hidden = true;\n    $(\"sample-button\").hidden = true;\n    $(\"end-button\").hidden = true;\n    $(\"end-button\").disabled = false;\n    $(\"camera-choice\").hidden = false;\n    $(\"camera-choice\").style.pointerEvents = \"\";\n    $(\"stage-actions\").hidden = false;\n    resetSignals();\n    renderScores(null);\n    updateConnectionUI();\n    window.scrollTo({ top: 0, behavior: \"smooth\" });\n  }\n\n  function openConnectionDialog() {\n    const dialog = $(\"connection-dialog\");\n    if (!dialog.open) dialog.showModal();\n  }\n  function closeConnectionDialog() { $(\"connection-dialog\").close(); }\n\n  document.querySelectorAll(\".focus-chip\").forEach(button => button.addEventListener(\"click\", () => chooseFocus(button)));\n  $(\"connection-pill\").addEventListener(\"click\", openConnectionDialog);\n  $(\"guide-button\").addEventListener(\"click\", openConnectionDialog);\n  $(\"dialog-close\").addEventListener(\"click\", closeConnectionDialog);\n  $(\"dialog-done\").addEventListener(\"click\", closeConnectionDialog);\n  $(\"connection-dialog\").addEventListener(\"click\", event => {\n    if (event.target === $(\"connection-dialog\")) closeConnectionDialog();\n  });\n  $(\"start-button\").addEventListener(\"click\", () => state.configured ? startLive() : startPreview());\n  $(\"sample-button\").addEventListener(\"click\", runSampleTurn);\n  $(\"end-button\").addEventListener(\"click\", endSession);\n  $(\"restart-button\").addEventListener(\"click\", restart);\n  $(\"mirror-play\").addEventListener(\"click\", playMirror);\n  $(\"camera-enabled\").addEventListener(\"change\", resetSignals);\n  window.addEventListener(\"pagehide\", () => {\n    if (state.call) {\n      try { state.call.leave(); } catch {}\n    }\n    if (state.conversationId && state.mode === \"live\") {\n      fetch(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/end`, {\n        method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: \"{}\", keepalive: true,\n      }).catch(() => {});\n    }\n  });\n\n  boot();\n})();\n";
const OG_BASE64 = "";

const json = (value, status = 200) => new Response(JSON.stringify(value), {
  status,
  headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
});

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    }
    if (url.pathname === "/static/live.css") {
      return new Response(CSS, { headers: { "content-type": "text/css; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (url.pathname === "/static/live.js") {
      return new Response(JS, { headers: { "content-type": "text/javascript; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (url.pathname === "/static/og.png") {
      const raw = atob(OG_BASE64);
      const bytes = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);
      return new Response(bytes, { headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" } });
    }
    if (url.pathname === "/api/tavus/status") {
      return json({
        configured: false,
        mode: "preview",
        pal_ready: false,
        mirror_voice_ready: false,
        capabilities: { face: "Phoenix", perception: "Raven-1", turn_taking: "Sparrow-1", emotion_recognition: "limited_on_managed_pal" },
      });
    }
    if (url.pathname === "/api/cards") {
      return json({ now: Math.floor(Date.now() / 1000), cards: [] });
    }
    if (url.pathname.startsWith("/api/tavus/conversations")) {
      return json({ error: "This hosted build is the guided preview. Configure the server-side integration to start a live room.", reason: "not_configured" }, 503);
    }
    return new Response("Not found", { status: 404 });
  },
};
